impl ToTokens for Success {
    fn to_tokens(&self, tokens: &mut TokenStream) {
        match self {
            Self::NoBody => tokens.append_all(quote!(())),
            Self::WithBody(body) => tokens.append_all(return_type(
                &body.property,
                Reference::Own,
                Some("'response"),
            )),
        }
    }
}
